style.css:
/* Review required before merging (Orange) */
a[aria-label="Review required before merging"] {
  background-color: #feb596;
  padding: 2pt 10pt;
  border-radius: 4pt;
  color: black !important;
}
a:hover[aria-label="Review required before merging"] {
  color: #4493f8 !important;
}


a[aria-label="1 review approval"] {
  background: repeating-linear-gradient(
    45deg,
    #FDD835,                         /* Start with yellow */
    #FDD835 8px,                     /* Stay yellow for 8 pixels */
    #4caf50 8px,                     /* Abruptly switch to light green */
    #4caf50 16px                      /* Stay light green for 16 pixels */
  );
  padding: 2pt 10pt;
  border-radius: 4pt;
  color: black !important;
}

/* This pseudo-element adds our new custom text */
a[aria-label="1 review approval"]::before {
  content: '1/2';
   padding: 2pt;
  border-radius: 4pt;
  color: black !important;
}

/* This handles the hover effect for our custom text */
a:hover[aria-label="1 review approval"]::before {
  color: #4493f8 !important;
}


/* 2+ review approvals (Solid Green) */
a[aria-label*=" review approval"]:not([aria-label="1 review approval"]) {
  background-color: #4caf50;
  padding: 2pt 10pt;
  border-radius: 4pt;
  color: black !important;
}
a:hover[aria-label*=" review approval"]:not([aria-label="1 review approval"]) {
  color: #82c3fd !important;
}


/* Requesting changes (Red-Orange) */
a[aria-label*=" requesting changes"] {
  background-color: #f0803d;
  padding: 2pt 10pt;
  border-radius: 4pt;
  color: black !important;
}
a:hover[aria-label*=" requesting changes"] {
  color: #4493f8 !important;
}
